// 生成 functions/api/_page-data.js
// 数据源：backend/data/pages/*.json（唯一权威）
// 用途：让 Cloudflare Functions 直接提供 /api/page-data/* 与 /api/ai-module/*，
//      避免这些请求被转发到旧 Worker 而返回过期内容。
const fs = require('fs');
const path = require('path');

const dir = path.join(__dirname, '..', 'backend', 'data', 'pages');
const out = {};
fs.readdirSync(dir)
    .filter(f => f.endsWith('.json'))
    .sort()
    .forEach(f => {
        out[f.replace(/\.json$/, '')] = JSON.parse(fs.readFileSync(path.join(dir, f), 'utf8'));
    });

const body =
    '// AUTO-GENERATED by tools/gen-page-data.js — do not edit.\n' +
    '// Source: backend/data/pages/*.json\n' +
    'const PAGE_DATA = ' + JSON.stringify(out) + ';\n' +
    'export default PAGE_DATA;\n';

fs.writeFileSync(path.join(__dirname, '..', 'functions', 'api', '_page-data.js'), body);
console.log('[gen-page-data] 模块数:', Object.keys(out).length, '| 大小:', Math.round(Buffer.byteLength(body) / 1024) + 'KB');
